alter table gov_repo.ict_incidents add column if not exists incident_category gov_repo.dora_incident_category not null default 'system_failure',add column if not exists is_major_incident boolean not null default false,add column if not exists major_classification_rationale text,add column if not exists criterion_clients_affected boolean not null default false,add column if not exists criterion_financial_threshold boolean not null default false,add column if not exists criterion_reputational_impact boolean not null default false,add column if not exists criterion_critical_service_down boolean not null default false,add column if not exists criterion_data_integrity_loss boolean not null default false,add column if not exists criterion_geographic_spread boolean not null default false,add column if not exists criterion_duration_exceeded boolean not null default false,add column if not exists clients_affected_count integer,add column if not exists clients_affected_pct numeric(5,2),add column if not exists transactions_affected_count bigint,add column if not exists geographic_regions_affected text[] not null default '{}',add column if not exists is_cyber_threat boolean not null default false,add column if not exists cyber_threat_indicator text,add column if not exists mitre_attack_techniques text[] not null default '{}';
alter table gov_repo.ict_incidents add column if not exists occurred_at timestamptz,add column if not exists detected_at timestamptz,add column if not exists detected_by varchar(100),add column if not exists detection_method varchar(100),add column if not exists triaged_at timestamptz,add column if not exists triaged_by uuid references gov_repo.governance_users(user_id),add column if not exists initial_severity gov_repo.incident_severity,add column if not exists contained_at timestamptz,add column if not exists containment_actions text,add column if not exists incident_commander_id uuid references gov_repo.governance_users(user_id),add column if not exists reporting_owner_id uuid references gov_repo.governance_users(user_id);
